-- Tool_Catalog registrations for the two-path analysis contract (generated from market-ai-orc tool definitions).
-- Inactive rows: market-ai-backend never lists them; market-ai-orc registers its tools in code.
BEGIN;

UPDATE public."Tool_Catalog"
SET tool_specific_limits = tool_specific_limits || '{"superseded_by": "v3"}'::jsonb, updated_at = CURRENT_TIMESTAMP
WHERE tool_name = 'create_analysis_spec' AND version = 'v2' AND tool_specific_limits->>'runtime_service' = 'market-ai-orc';

UPDATE public."Tool_Catalog"
SET tool_specific_limits = tool_specific_limits || '{"superseded_by": "v4"}'::jsonb, updated_at = CURRENT_TIMESTAMP
WHERE tool_name = 'run_python_analysis' AND version = 'v3' AND tool_specific_limits->>'runtime_service' = 'market-ai-orc';

UPDATE public."Tool_Catalog"
SET tool_specific_limits = tool_specific_limits || '{"model_facing": "AI_ENABLE_REQUEST_DATA (default false): data requests of the analysis path are compiled by prepare_analysis_data"}'::jsonb,
    updated_at = CURRENT_TIMESTAMP
WHERE tool_name = 'request_data' AND tool_specific_limits->>'runtime_service' = 'market-ai-orc'
  AND version = (SELECT max(version) FROM public."Tool_Catalog" WHERE tool_name = 'request_data'
                 AND tool_specific_limits->>'runtime_service' = 'market-ai-orc');

INSERT INTO public."Tool_Catalog" (
    tool_name, tool_family, tool_type, purpose, input_schema, output_schema,
    execution_type, handler_name, default_output_rows, max_output_rows,
    max_input_rows, max_tickers, max_date_range_days, max_estimated_rows,
    timeout_seconds, max_output_bytes, max_llm_result_rows,
    max_llm_result_bytes, max_llm_result_tokens,
    requires_analytics_worker, requires_feature_catalog, requires_data_readiness,
    tool_specific_limits, version, is_active
)
VALUES
    ('get_dimension_values', 'DISCOVERY', 'RETRIEVAL', 'List the exact stored values of one category column (a groupable text column of a static catalog table), optionally only those containing match. Use it to write a scope predicate or a grouping key with the exact data value (for example the stored spelling of a classification the user named). Returns values only, at most 200, never counts or measures: it is not a data answer.', '{"additionalProperties":false,"properties":{"column":{"description":"A groupable text column of that table (not its entity column).","type":"string"},"match":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"Case-insensitive part of the value you look for (e.g. a word from the request), or null for every value."},"table":{"description":"A static catalog table (no time column), e.g. a reference table of classifications.","type":"string"}},"required":["table","column","match"],"type":"object"}'::jsonb, '{"description":"VALUES_READY with the canonical values of one dimension column (no counts), or a refusal with a reason_code.","properties":{"column":{},"decision":{},"match":{},"message":{},"note":{},"reason_code":{},"status":{},"table":{},"truncated":{},"values":{}},"type":"object"}'::jsonb,
     'ORCHESTRATOR', NULL, NULL, 200, NULL, NULL, NULL, 2000, 30, 20000, 200, 20000, NULL,
     false, false, false, '{"eligible_columns":"AI-allowed, non-sensitive, groupable text columns of active BOUNDED_READ static tables; never the entity column","executor_service":"market-sql-governor","governor_endpoint":"POST /v1/catalog/dimension-values (orc key)","handler":"app/tools/request_data.py","match_length":[1,60],"max_returned_values":200,"refusal_codes":["TABLE_NOT_APPROVED","UNKNOWN_COLUMN","DIMENSION_VALUES_STATIC_ONLY","DIMENSION_IS_ENTITY","NOT_A_DIMENSION","HIGH_CARDINALITY"],"registry_state":"Registered in market-ai-orc; is_active=false keeps it out of market-ai-backend tool lists.","returns_counts":false,"runtime_service":"market-ai-orc","scan_limit_distinct_values":2000}'::jsonb, 'v1', false),
    ('create_analysis_spec', 'ADVANCED', 'VALIDATION', 'Required before any analysis: propose the one machine-readable contract (Analysis Spec V2) of the calculation. The service checks every table, column, relationship, frequency and subject against the catalog and the spec against the user''s own messages, and returns APPROVED (with spec_id), APPROVED_WITH_UNVERIFIED (spec_id plus interpretations the user did not state, which must be disclosed), ANALYSIS_SPEC_MISMATCH (fix the spec to match the request; never change the request to fit limits), NEEDS_CLARIFICATION (ask the user), INVALID_SPEC (fix each problem; its code is in parentheses), or for RESEARCH specs the Research Governor''s REPLAN_REQUIRED or REJECTED. The same spec again returns the same spec_id. After approval call prepare_analysis_data(spec_id): the backend compiles and extracts exactly the approved scope; you never restate the scope as a data request. subject and source tables: copy data_domain, entity_type and asset_type from discover_catalog; every PRIMARY_DATA and UNIVERSE input table must have that subject. scope: ALL_ELIGIBLE (every entity in the source), ENTITY_LIST (entities), or ATTRIBUTE_FILTER (predicates on filterable catalog columns, all must hold; e.g. a classification column EQ a value). A predicate names the input whose table has the column; when it restricts another input (for example prices restricted by a column of a reference table), list the catalog relationship_id that joins the two tables. Use the exact data value; provenance CATALOG_RESOLVED with user_text = the user''s own words when you mapped words to a catalog value. time_scope: null for static reference data (a count per group of a table without a time column); otherwise mode, dates or count/unit, and a frequency the tables support. provenance per requirement: USER_EXPLICIT only for what the user stated, USER_CLARIFIED for answers to your clarification question, APPROVED_DEFAULT with default_id for a documented default (a parameter without a documented default is left null instead), AI_INFERRED otherwise; CATALOG_RESOLVED (user words mapped to catalog values) only on scope, scope predicates and segments. Definitions follow TA-Lib first, then AI_formula_reference, then your own formula (CUSTOM). Defaults: DEFAULT_TRAILING_CALENDAR_WINDOW (''last N months'' = TRAILING), DEFAULT_TRADING_DAYS, DEFAULT_LATEST, DEFAULT_MONTH_WITHOUT_YEAR, DEFAULT_UNIVERSE_ALL_IN_SOURCE (''all stocks''), DEFAULT_FREQUENCY_DAILY, DEFAULT_ROLLING_WINDOW_UNIT, DEFAULT_STD_DDOF (0, TA-Lib STDDEV), DEFAULT_ZSCORE_DDOF (1), DEFAULT_ZSCORE_INCLUDES_CURRENT (true for a price, false for a return series), DEFAULT_RETURN_KIND (SIMPLE), DEFAULT_RETURN_HORIZON (1), DEFAULT_RETURN_AS_PERCENT (false), DEFAULT_RSI_PERIOD (14), DEFAULT_RSI_SMOOTHING (WILDER, TA-Lib), DEFAULT_FORWARD_RETURN_ENTRY (NEXT_OPEN: close[t+h] / open[t+1] - 1; SIGNAL_CLOSE only when the user asks), DEFAULT_CORRELATION_METHOD, DEFAULT_CORRELATION_TRANSFORM (SIMPLE_RETURN), DEFAULT_CORRELATION_MIN_OVERLAP, DEFAULT_EVENT_OVERLAP_POLICY (NON_OVERLAPPING), DEFAULT_EVENT_BASELINE (ALL_ELIGIBLE), DEFAULT_EVENT_MIN_EVENTS (30), DEFAULT_ZERO_DENOMINATOR (NULL), DEFAULT_PERIOD_RETURN_BASE (PREVIOUS_OBSERVATION), DEFAULT_GROUP_MISSING_KEY (SEPARATE_GROUP), DEFAULT_GROUP_UNKNOWN_VALUES ([]), DEFAULT_GROUP_MIN_OBSERVATIONS (1), DEFAULT_RANK_TIE_POLICY (INCLUDE_EXACTLY_N_STABLE), DEFAULT_PERIOD_STD_DDOF (1, not annualized), DEFAULT_PERIOD_STAT_MIN_OBSERVATIONS (1), DEFAULT_SERIES_ALIGNMENT (COMMON_DATES: no forward fill, lag 0), DEFAULT_GROUP_PER_DATE (false), DEFAULT_ROLLING_CORRELATION_TRANSFORM (NONE). Omitted method parameters get their default. Methods with independent recalculation (params): SMA(window), ROLLING_STD(window, ddof), ROLLING_ZSCORE(window, ddof, include_current), RETURN(horizon, kind SIMPLE|LOG, as_percent), PERIOD_RETURN(kind, as_percent, base PREVIOUS_OBSERVATION|FIRST_IN_PERIOD; the change over the whole period, one column), FORWARD_RETURN(horizon, kind, as_percent, entry NEXT_OPEN|SIGNAL_CLOSE; columns [close, open] for NEXT_OPEN, [close] for SIGNAL_CLOSE), RSI(period), ROLLING_CORRELATION(window, method, transform; two columns), CORRELATION(method, transform, min_overlap; ENTITY_PAIR output over an ENTITY_LIST scope), PERIOD_STAT(function AVG|MEDIAN|STD|MIN|MAX|SUM|COUNT, ddof for STD, min_observations; one column or input_calculation; the statistic of each entity''s observations inside the period, e.g. volatility = STD of a 1-observation RETURN; never substitute a stored annualized or rolling feature column), GROUP_AGGREGATE(function COUNT|COUNT_DISTINCT|SUM|AVG|MEDIAN|MIN|MAX, per_date, missing_group_policy SEPARATE_GROUP|EXCLUDE, unknown_group_values [values treated as unknown], min_observations; one column or input_calculation = a per-entity calculation such as PERIOD_RETURN or PERIOD_STAT; group_by = catalog grouping columns of any input, mapped to entities by entity column; or segments = [{label, predicates [{input, column, operator, value}], provenance, user_text}] when the groups are defined on different columns (an entity belongs to every segment whose predicates all hold; key column segment); per_date true gives one aligned series per group), GROUP_CORRELATION(method, min_overlap, alignment; no columns; input_calculation = a per_date GROUP_AGGREGATE with one key or segments; GROUP_PAIR output with key_columns [<key>_a, <key>_b], one row per pair of groups; also emit the GROUP_DATE series). Averaging a return across entities over a period: say which return the user asked for (PERIOD_RETURN = the return over the whole period, or PERIOD_STAT AVG of a daily RETURN); when the user did not say, the service returns NEEDS_CLARIFICATION. EVENT_STUDY(min_events, overlap_policy, baseline; no columns; input_calculation = the FORWARD_RETURN outcome; signal = predicates on earlier trailing calculations; one SUMMARY output with columns segment, event_count, mean, median, hit_rate, baseline_count, baseline_mean, baseline_median, delta_mean, censored_count, overlapping_dropped and rows ALL, plus IN_SAMPLE and OUT_OF_SAMPLE when research.holdout is set). Any other formula is CUSTOM with formula, time_alignment, covers, and ideally an expression, which is recalculated independently: input columns and earlier calculation ids with + - * / **, comparisons, & | ~, abs, log, exp, sqrt, sign, min, max, where(c, a, b), lag(x, k), rolling_sum(x, n), rolling_mean(x, n) (past only). A CUSTOM without an expression is never independently recalculated (optional warmup_observations param). Add formula_refs (CALC_### ids it adapts), meaning, and unit to CUSTOM. Chain a method on another calculation with input_calculation (e.g. ROLLING_STD of a RETURN). outputs: each TABLE the code emits, by name. grain ENTITY_DATE (one row per entity and date in the period), ENTITY (one row per entity at its latest observation in the period), ENTITY_PAIR, GROUP (one row per group; key_columns = the group_by columns or [segment]), GROUP_DATE (per group and date; per_date true), GROUP_PAIR (GROUP_CORRELATION), SUMMARY (EVENT_STUDY), or UNSPECIFIED (not checkable). coverage FULL (every entity/date/group in scope) or SELECTION (rows meeting the selection predicates, e.g. RSI < 30, or the top-N of a ranking {calculation, direction, limit, tie_policy}). Only declared outputs with a checkable grain can pass validation. research: null when analysis_type is ANALYSIS. For RESEARCH set evidence_standard (HISTORICAL_PATTERN, PREDICTIVE, EXPLORATORY, DESCRIPTIVE, SCENARIO for hypotheticals), objective, hypothesis {id H1.., statement} (required for HISTORICAL_PATTERN and PREDICTIVE), design_type and primary_metric (the calculation the claim is about): EVENT_STUDY (an EVENT_STUDY calculation), COMPARATIVE (a GROUP_AGGREGATE AVG of a per-entity metric in a GROUP output; comparator GROUPS or ALL_OTHERS), ASSOCIATION (a CORRELATION or GROUP_CORRELATION), PREDICTIVE_TEMPORAL (evidence_standard PREDICTIVE: an EVENT_STUDY with holdout {start} inside the period), EXPLORATORY_SEARCH (evidence_standard EXPLORATORY; candidates = the size of the search space). A design with more than one comparison needs candidates >= the number of comparisons and multiple_testing_policy BONFERRONI. method_ref (AI_research_catalog method_id), and followup_of (spec_id of a completed experiment on the same hypothesis) for a follow-up; a non-significant result is reported, never searched again until it passes.', '{"additionalProperties":false,"properties":{"analysis_type":{"description":"ANALYSIS for a calculation, statistic, ranking or aggregate (research null); RESEARCH for a historical-pattern, predictive, exploratory or scenario question (research block required).","enum":["ANALYSIS","RESEARCH"],"type":"string"},"calculations":{"items":{"additionalProperties":false,"properties":{"columns":{"description":"Input columns ([] when input_calculation is set).","items":{"type":"string"},"type":"array"},"covers":{"anyOf":[{"items":{"enum":["RSI","SMA","STD","ZSCORE","RETURN","FORWARD_RETURN","CORRELATION","EVENT_STUDY"],"type":"string"},"type":"array"},{"type":"null"}],"description":"CUSTOM only: requested method families it implements."},"data_policies":{"anyOf":[{"additionalProperties":false,"properties":{"missing":{"enum":["PROPAGATE"],"type":"string"},"zero_denominator":{"enum":["NULL","ZERO"],"type":"string"}},"required":["zero_denominator","missing"],"type":"object"},{"type":"null"}],"description":"CUSTOM only: zero_denominator NULL (default) or ZERO; missing PROPAGATE."},"dataset":{"description":"Logical input name.","type":"string"},"default_id":{"anyOf":[{"type":"string"},{"type":"null"}]},"expression":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"CUSTOM only: recalculable expression over the input columns and earlier calculation ids, e.g. rolling_sum(net_value, 20) / rolling_sum(value, 20); null for free-form code that cannot be recalculated."},"formula":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"Required for CUSTOM; null for other methods."},"formula_refs":{"anyOf":[{"items":{"type":"string"},"type":"array"},{"type":"null"}],"description":"CUSTOM only: AI_formula_reference ids (CALC_###) the formula adapts; null if none."},"group_by":{"anyOf":[{"items":{"additionalProperties":false,"properties":{"column":{"type":"string"},"input":{"description":"Input holding the grouping column.","type":"string"}},"required":["input","column"],"type":"object"},"type":"array"},{"type":"null"}],"description":"GROUP_AGGREGATE only: 1-3 catalog grouping columns (group_by_allowed); else null."},"id":{"type":"string"},"input_calculation":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"id of an earlier calculation used as input, or null."},"meaning":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"CUSTOM only: what the value means financially."},"method":{"enum":["SMA","ROLLING_STD","ROLLING_ZSCORE","RETURN","FORWARD_RETURN","RSI","ROLLING_CORRELATION","CORRELATION","EVENT_STUDY","PERIOD_RETURN","PERIOD_STAT","GROUP_AGGREGATE","GROUP_CORRELATION","CUSTOM"],"type":"string"},"output_column":{"description":"Column holding this value in the outputs.","type":"string"},"params":{"items":{"additionalProperties":false,"properties":{"default_id":{"anyOf":[{"type":"string"},{"type":"null"}]},"name":{"type":"string"},"provenance":{"enum":["USER_EXPLICIT","USER_CLARIFIED","APPROVED_DEFAULT","AI_INFERRED"],"type":"string"},"value":{"anyOf":[{"type":"integer"},{"type":"number"},{"type":"string"},{"type":"boolean"},{"items":{"anyOf":[{"type":"string"},{"type":"integer"},{"type":"number"}]},"type":"array"},{"type":"null"}],"description":"The parameter value; null applies the method''s approved default (recorded as APPROVED_DEFAULT)."}},"required":["name","value","provenance","default_id"],"type":"object"},"type":"array"},"provenance":{"enum":["USER_EXPLICIT","USER_CLARIFIED","APPROVED_DEFAULT","AI_INFERRED"],"type":"string"},"segments":{"anyOf":[{"items":{"additionalProperties":false,"properties":{"label":{"description":"The group''s key value.","type":"string"},"predicates":{"description":"All must hold.","items":{"additionalProperties":false,"properties":{"column":{"description":"A filterable catalog column.","type":"string"},"input":{"description":"The input whose table holds the column.","type":"string"},"operator":{"enum":["EQ","NEQ","IN","GT","GTE","LT","LTE","IS_NULL","IS_NOT_NULL"],"type":"string"},"value":{"anyOf":[{"type":"string"},{"type":"integer"},{"type":"number"},{"type":"boolean"},{"items":{"anyOf":[{"type":"string"},{"type":"integer"},{"type":"number"}]},"type":"array"},{"type":"null"}],"description":"Scalar; a list for IN; null for IS_NULL / IS_NOT_NULL. Use the exact catalog data value."}},"required":["input","column","operator","value"],"type":"object"},"type":"array"},"provenance":{"enum":["USER_EXPLICIT","USER_CLARIFIED","CATALOG_RESOLVED","APPROVED_DEFAULT","AI_INFERRED"],"type":"string"},"user_text":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"CATALOG_RESOLVED: the user''s words this segment stands for, verbatim; else null."}},"required":["label","predicates","provenance","user_text"],"type":"object"},"type":"array"},{"type":"null"}],"description":"GROUP_AGGREGATE only, instead of group_by: labelled groups defined by predicates (for groups one column cannot express); else null."},"signal":{"anyOf":[{"items":{"additionalProperties":false,"properties":{"calculation":{"type":"string"},"default_id":{"anyOf":[{"type":"string"},{"type":"null"}]},"op":{"enum":[">",">=","<","<=","==","!="],"type":"string"},"provenance":{"enum":["USER_EXPLICIT","USER_CLARIFIED","APPROVED_DEFAULT","AI_INFERRED"],"type":"string"},"value":{"type":"number"}},"required":["calculation","op","value","provenance","default_id"],"type":"object"},"type":"array"},{"type":"null"}],"description":"EVENT_STUDY only: predicates on earlier trailing calculations that define an event (all must hold at t); null otherwise."},"time_alignment":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"Required for CUSTOM; null otherwise."},"unit":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"CUSTOM only: unit of the value (ratio, IDR, percent)."}},"required":["id","method","dataset","columns","input_calculation","params","output_column","formula","time_alignment","covers","signal","expression","formula_refs","meaning","unit","data_policies","group_by","segments","provenance","default_id"],"type":"object"},"type":"array"},"exclusion_rules":{"items":{"additionalProperties":false,"properties":{"default_id":{"anyOf":[{"type":"string"},{"type":"null"}]},"provenance":{"enum":["USER_EXPLICIT","USER_CLARIFIED","APPROVED_DEFAULT","AI_INFERRED"],"type":"string"},"rule":{"enum":["MIN_OBSERVATIONS_IN_PERIOD","MAX_STALENESS_DAYS","EXCLUDE_TICKERS"],"type":"string"},"value":{"anyOf":[{"type":"integer"},{"items":{"type":"string"},"type":"array"}]}},"required":["rule","value","provenance","default_id"],"type":"object"},"type":"array"},"inputs":{"items":{"additionalProperties":false,"properties":{"columns":{"description":"Columns the analysis needs.","items":{"type":"string"},"type":"array"},"date_column":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"null: the catalog time_column."},"entity_column":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"null: the catalog entity_column."},"name":{"description":"Logical input name, e.g. prices.","type":"string"},"role":{"description":"PRIMARY_DATA (measured observations), UNIVERSE (defines the entities in scope), or REFERENCE (unscoped lookup table).","enum":["PRIMARY_DATA","UNIVERSE","REFERENCE"],"type":"string"},"source_table":{"description":"Catalog table the data comes from.","type":"string"}},"required":["name","source_table","role","entity_column","date_column","columns"],"type":"object"},"type":"array"},"outputs":{"items":{"additionalProperties":false,"properties":{"calculations":{"items":{"type":"string"},"type":"array"},"coverage":{"enum":["FULL","SELECTION"],"type":"string"},"date_column":{"anyOf":[{"type":"string"},{"type":"null"}]},"entity_column":{"anyOf":[{"type":"string"},{"type":"null"}]},"grain":{"enum":["ENTITY_DATE","ENTITY","ENTITY_PAIR","GROUP","GROUP_DATE","GROUP_PAIR","SUMMARY","UNSPECIFIED"],"type":"string"},"key_columns":{"anyOf":[{"items":{"type":"string"},"type":"array"},{"type":"null"}],"description":"The output''s key columns (entity, grouping columns, date); null derives them."},"name":{"description":"The name the code passes to emit_table.","type":"string"},"pair_columns":{"anyOf":[{"items":{"type":"string"},"type":"array"},{"type":"null"}],"description":"Two entity columns for ENTITY_PAIR, else null."},"ranking":{"anyOf":[{"additionalProperties":false,"properties":{"calculation":{"type":"string"},"default_id":{"anyOf":[{"type":"string"},{"type":"null"}]},"direction":{"enum":["ASC","DESC"],"type":"string"},"limit":{"type":"integer"},"provenance":{"enum":["USER_EXPLICIT","USER_CLARIFIED","APPROVED_DEFAULT","AI_INFERRED"],"type":"string"},"tie_policy":{"enum":["INCLUDE_EXACTLY_N_STABLE","INCLUDE_TIES"],"type":"string"}},"required":["calculation","direction","limit","tie_policy","provenance","default_id"],"type":"object"},{"type":"null"}],"description":"Top-N of one calculation over every in-scope candidate (ENTITY or GROUP grain, coverage SELECTION); else null."},"selection":{"anyOf":[{"items":{"additionalProperties":false,"properties":{"calculation":{"type":"string"},"default_id":{"anyOf":[{"type":"string"},{"type":"null"}]},"op":{"enum":[">",">=","<","<=","==","!="],"type":"string"},"provenance":{"enum":["USER_EXPLICIT","USER_CLARIFIED","APPROVED_DEFAULT","AI_INFERRED"],"type":"string"},"value":{"type":"number"}},"required":["calculation","op","value","provenance","default_id"],"type":"object"},"type":"array"},{"type":"null"}],"description":"Predicates for SELECTION, else null."}},"required":["name","grain","coverage","calculations","selection","entity_column","date_column","pair_columns","key_columns","ranking"],"type":"object"},"type":"array"},"question":{"description":"The analytical request, restated.","type":"string"},"relationships":{"description":"Catalog relationships joining input tables (needed when a scope predicate is on another input''s table).","items":{"additionalProperties":false,"properties":{"relationship_id":{"description":"Catalog relationship_id joining two input tables.","type":"integer"}},"required":["relationship_id"],"type":"object"},"type":"array"},"research":{"anyOf":[{"additionalProperties":false,"properties":{"candidates":{"anyOf":[{"type":"integer"},{"type":"null"}],"description":"Conditions, lags or combinations this experiment evaluates; null = 1."},"comparator":{"anyOf":[{"additionalProperties":false,"properties":{"groups":{"anyOf":[{"items":{"type":"string"},"type":"array"},{"type":"null"}],"description":"The group key values compared (null = every group)."},"type":{"description":"GROUPS: every pair of the compared groups; ALL_OTHERS: each compared group versus every other in-scope entity.","enum":["GROUPS","ALL_OTHERS"],"type":"string"}},"required":["type","groups"],"type":"object"},{"type":"null"}],"description":"COMPARATIVE: what the groups are compared with; else null."},"design_type":{"anyOf":[{"enum":["EVENT_STUDY","COMPARATIVE","ASSOCIATION","PREDICTIVE_TEMPORAL","EXPLORATORY_SEARCH"],"type":"string"},{"type":"null"}],"description":"The research design; required for HISTORICAL_PATTERN, PREDICTIVE and EXPLORATORY."},"evidence_standard":{"enum":["CALCULATION","SCREEN","DESCRIPTIVE","HISTORICAL_PATTERN","EXPLORATORY","PREDICTIVE","SCENARIO"],"type":"string"},"followup_of":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"spec_id of the completed experiment this follows up, or null."},"holdout":{"anyOf":[{"additionalProperties":false,"properties":{"end":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"Last out-of-sample date, or null."},"start":{"description":"First out-of-sample date (YYYY-MM-DD).","type":"string"}},"required":["start","end"],"type":"object"},{"type":"null"}]},"hypothesis":{"anyOf":[{"additionalProperties":false,"properties":{"id":{"description":"H1, H2, ...","type":"string"},"statement":{"type":"string"}},"required":["id","statement"],"type":"object"},{"type":"null"}]},"method_ref":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"AI_research_catalog method_id used as methodology reference, or null."},"multiple_testing_policy":{"anyOf":[{"enum":["NONE","BONFERRONI"],"type":"string"},{"type":"null"}],"description":"BONFERRONI when the design makes more than one comparison; NONE only for a single test."},"objective":{"type":"string"},"observation_unit":{"anyOf":[{"enum":["ENTITY","ENTITY_DATE","GROUP","GROUP_DATE","PAIR","EVENT"],"type":"string"},{"type":"null"}],"description":"The unit one observation of the evidence is; null derives it from the design."},"primary_metric":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"id of the calculation the claim is about."}},"required":["evidence_standard","objective","hypothesis","method_ref","followup_of","candidates","holdout","design_type","primary_metric","observation_unit","comparator","multiple_testing_policy"],"type":"object"},{"type":"null"}],"description":"null for a plain calculation, screen, or description. For research (a historical pattern, predictive, exploratory, or scenario question) the experiment''s evidence standard, hypothesis, and follow-up link; the Research Governor approves it against the run''s budget."},"scope":{"additionalProperties":false,"properties":{"default_id":{"anyOf":[{"type":"string"},{"type":"null"}]},"entities":{"anyOf":[{"items":{"type":"string"},"type":"array"},{"type":"null"}],"description":"ENTITY_LIST: entity values; else null."},"predicates":{"anyOf":[{"items":{"additionalProperties":false,"properties":{"column":{"description":"A filterable catalog column.","type":"string"},"input":{"description":"The input whose table holds the column.","type":"string"},"operator":{"enum":["EQ","NEQ","IN","GT","GTE","LT","LTE","IS_NULL","IS_NOT_NULL"],"type":"string"},"provenance":{"enum":["USER_EXPLICIT","USER_CLARIFIED","CATALOG_RESOLVED","APPROVED_DEFAULT","AI_INFERRED"],"type":"string"},"table":{"type":"string"},"user_text":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"CATALOG_RESOLVED: the user''s words this value resolves, verbatim; else null."},"value":{"anyOf":[{"type":"string"},{"type":"integer"},{"type":"number"},{"type":"boolean"},{"items":{"anyOf":[{"type":"string"},{"type":"integer"},{"type":"number"}]},"type":"array"},{"type":"null"}],"description":"Scalar; a list for IN; null for IS_NULL / IS_NOT_NULL. Use the exact catalog data value."}},"required":["input","table","column","operator","value","provenance","user_text"],"type":"object"},"type":"array"},{"type":"null"}],"description":"ATTRIBUTE_FILTER: 1-8 predicates, all must hold; else null."},"provenance":{"enum":["USER_EXPLICIT","USER_CLARIFIED","CATALOG_RESOLVED","APPROVED_DEFAULT","AI_INFERRED"],"type":"string"},"selection_type":{"enum":["ALL_ELIGIBLE","ENTITY_LIST","ATTRIBUTE_FILTER"],"type":"string"}},"required":["selection_type","entities","predicates","provenance","default_id"],"type":"object"},"spec_version":{"enum":["2.0"],"type":"string"},"subject":{"additionalProperties":false,"properties":{"asset_type":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"The tables'' asset_type from discover_catalog; null when it has none."},"data_domain":{"description":"The tables'' data_domain from discover_catalog.","type":"string"},"entity_type":{"description":"The tables'' entity_type from discover_catalog.","type":"string"}},"required":["data_domain","entity_type","asset_type"],"type":"object"},"time_scope":{"anyOf":[{"additionalProperties":false,"properties":{"count":{"anyOf":[{"type":"integer"},{"type":"null"}],"description":"Units for TRAILING, dates for TRADING_DAYS, else