     'ORCHESTRATOR', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 50, 20000, 50, 20000, NULL,
     false, false, false, '{"analysis_types":["ANALYSIS","RESEARCH"],"catalog_contract_source":"market-sql-governor POST /v1/catalog/contract","executor_service":"market-python-sandbox","handler":"app/tools/analysis.py","max_scope_predicates":8,"max_segment_predicates":4,"max_segments":10,"methods":["SMA","ROLLING_STD","ROLLING_ZSCORE","RETURN","PERIOD_RETURN","PERIOD_STAT","FORWARD_RETURN","RSI","ROLLING_CORRELATION","CORRELATION","GROUP_AGGREGATE","GROUP_CORRELATION","EVENT_STUDY","CUSTOM"],"model_facing_version":"2.0","multiple_testing_policies":["NONE","BONFERRONI"],"output_grains":["ENTITY_DATE","ENTITY","ENTITY_PAIR","GROUP","GROUP_DATE","GROUP_PAIR","SUMMARY","UNSPECIFIED"],"predicate_operators":["EQ","NEQ","IN","GT","GTE","LT","LTE","IS_NULL","IS_NOT_NULL"],"provenance_values":["USER_EXPLICIT","USER_CLARIFIED","CATALOG_RESOLVED","APPROVED_DEFAULT","AI_INFERRED"],"ranking_max_limit":100,"registry_state":"Registered in market-ai-orc; is_active=false keeps it out of market-ai-backend tool lists.","research_designs":["EVENT_STUDY","COMPARATIVE","ASSOCIATION","PREDICTIVE_TEMPORAL","EXPLORATORY_SEARCH"],"return_basis_clarification":"NEEDS_CLARIFICATION when a return averaged across entities over a period has no stated basis","runtime_service":"market-ai-orc","scope_selection_types":["ALL_ELIGIBLE","ENTITY_LIST","ATTRIBUTE_FILTER"],"spec_versions_accepted_by_sandbox":["analysis_spec/v1","analysis_spec/v2"],"time_scope":"null only when every input is static","validation_profiles":{"ANALYSIS":"Y_ANALYSIS","RESEARCH":"X_RESEARCH"}}'::jsonb, 'v3', false),
    ('prepare_analysis_data', 'ADVANCED', 'RETRIEVAL', 'Prepare the governed input data of an approved spec: the backend compiles the spec''s approved scope (tables, relationships, predicates, entities, warm-up date range) into data requests, the SQL Governor validates and extracts them, and large extractions are split into date partitions without changing the scope. Returns status READY with input_bundle_id (pass it to run_python_analysis) and, per logical input, row counts and completeness; or NEEDS_NARROWING / REJECTED with a structured rejection (stage, reason_code, observed, limit, allowed_actions, forbidden_actions, retryable). Never change the user''s scope to pass a limit: revise the spec only when the rejection says the spec itself is wrong, otherwise report the limitation.', '{"additionalProperties":false,"properties":{"spec_id":{"description":"spec_id of an approved Analysis Spec V2.","type":"string"}},"required":["spec_id"],"type":"object"}'::jsonb, '{"description":"READY with input_bundle_id and per-input datasets, or NEEDS_NARROWING/REJECTED with a structured rejection.","properties":{"data_plan_id":{},"input_bundle_id":{},"inputs":{},"next_action":{},"prepared_inputs":{},"rejection":{},"scope_sha256":{},"spec_id":{},"status":{}},"type":"object"}'::jsonb,
     'ORCHESTRATOR', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 50, 40000, 50, 40000, NULL,
     false, false, false, '{"bundle_ttl_hours":4,"compiler":"market-ai-orc app/tools/data_compiler.py (DataRequestCompiler)","forbidden_actions":["CHANGE_USER_SCOPE","SAMPLE_WITHOUT_PERMISSION","DROP_ENTITIES","SHORTEN_PERIOD","CHANGE_METRIC"],"governor_endpoint":"POST /v1/query with data-plan lineage","max_date_partitions":16,"model_controls":["spec_id"],"partition_reasons":["DATE_RANGE_TOO_LARGE","ESTIMATED_SCAN_TOO_LARGE","ESTIMATED_RESULT_TOO_LARGE","DATASET_TOO_LARGE","QUERY_TIMEOUT","ESTIMATED_COST_TOO_LARGE"],"registry_state":"Registered in market-ai-orc; is_active=false keeps it out of market-ai-backend tool lists.","runtime_service":"market-ai-orc","scope_proof":"market-python-sandbox compares every bound dataset''s executed scope with the approved data plan"}'::jsonb, 'v1', false),
    ('run_python_analysis', 'ADVANCED', 'COMPUTATION', 'Run Python analysis in an isolated sandbox against an approved spec_id and the input_bundle_id that prepare_analysis_data returned for it (the prepared datasets are bound to the spec''s logical inputs by the backend). The code runs without network, subprocess, or file access outside its workspace. The helper module saniti and its functions, pandas as pd and numpy as np are already imported. Inputs are DuckDB views named after the logical inputs. load(name, columns=[...]) returns the whole input as a pandas DataFrame sorted by entity and date (date columns hold datetime.date objects; use pd.to_datetime for Timestamps), including the warm-up history before the analysis period; sql(''SELECT ... FROM prices WHERE ...'', [params]) runs DuckDB SQL (filter and aggregate in SQL; large results are refused). Compute every indicator per entity on that full date-sorted history, then keep the period rows with out = df[in_period(df)], which applies the approved period (including LATEST and trading-day periods) the same way the validator does; never cut the input to the period before computing. INPUTS lists each input''s columns; SPEC is the approved spec; ANALYSIS_START, ANALYSIS_END and REFERENCE_DATE are the resolved period. Write intermediate Parquet only to intermediate_path(name). Libraries: numpy 2, pandas 3 (groupby().apply drops the grouping columns; prefer groupby()[col].transform), polars, pyarrow, duckdb, scipy, statsmodels, matplotlib, TA-Lib (import talib). Helpers: iter_series, prepare_panel, panel_check, add_warning. Emit every spec output with emit_table(output_name, dataframe, description='''') (no other arguments); the dataframe''s columns must include the output''s key columns (entity_column, date_column, pair_columns, or the group key columns) and the output_column of each calculation it lists; a ranked output holds exactly its top-N rows. Also emit_metrics(dict), emit_chart(figure, name, title, description), emit_artifact(name, data, format). print() is not a result, and nothing the code reports about itself counts as evidence. The result has execution_status and validation_status (PASS, INCOMPLETE, FAILED, UNVERIFIED) with validation_level, reason_codes, expected_scope, actual_scope and validation_evidence (including scope.lineage: the executed scope equals the approved scope); a CALCULATION_MISMATCH can carry a diagnosis naming the parameter or procedure the values match. evidence_assessment says what the validated evidence supports for the spec''s evidence standard (decision SUPPORTED, PARTIALLY_SUPPORTED, INSUFFICIENT_EVIDENCE or INVALID, evidence_level, checks, the validator''s own statistics) and the reporting_constraints your answer must follow. CUSTOM code without an expression is re-run on data truncated at a cutoff date: values that change reveal look-ahead (TEMPORAL_LEAKAGE_DETECTED).', '{"additionalProperties":false,"properties":{"expected_outputs":{"description":"Output types the code will emit (unique).","items":{"enum":["TABLE","METRICS","CHART","ARTIFACT"],"type":"string"},"type":"array"},"input_bundle_id":{"description":"input_bundle_id from prepare_analysis_data for this spec_id.","type":"string"},"python_code":{"description":"Python source to run in the sandbox.","type":"string"},"spec_id":{"description":"spec_id of an approved analysis spec.","type":"string"}},"required":["spec_id","input_bundle_id","python_code","expected_outputs"],"type":"object"}'::jsonb, '{"description":"The market-python-sandbox analysis record (model view): execution, validation (including scope.lineage evidence), and the post-run evidence assessment are separate.","properties":{"actual_scope":{},"analysis_id":{},"database_features":{},"derived_features":{},"diagnostics":{},"error":{},"evidence_assessment":{},"execution_status":{},"expected_outputs":{},"expected_scope":{},"inputs":{},"leakage_check":{},"lineage":{},"next_action":{},"outputs":{},"outputs_expire_at":{},"question":{},"reason_codes":{},"retry_after_seconds":{},"runtime_ms":{},"spec_id":{},"validation_evidence":{},"validation_level":{},"validation_status":{},"warnings":{}},"type":"object"}'::jsonb,
     'ORCHESTRATOR', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 50, 40000, 50, 40000, NULL,
     false, false, false, '{"executor_service":"market-python-sandbox","handler":"app/tools/analysis.py","input_binding":"input_bundle_id from prepare_analysis_data (server-side bindings)","registry_state":"Registered in market-ai-orc; is_active=false keeps it out of market-ai-backend tool lists.","runtime_service":"market-ai-orc","scope_lineage_codes":["SCOPE_LINEAGE_MISSING","SCOPE_LINEAGE_MISMATCH","EXECUTED_SCOPE_MISMATCH","CATALOG_VERSION_MISMATCH","PARTITION_MISSING","PARTITION_GAP","PARTITION_OVERLAP","PARTITION_DUPLICATE","DATE_RANGE_NOT_COVERED"],"validation_levels":["EXECUTION_ONLY","SCOPE_VERIFIED","CALCULATION_VERIFIED"],"validation_statuses":["PENDING","PASS","INCOMPLETE","FAILED","UNVERIFIED"]}'::jsonb, 'v4', false);

DO $verify$
BEGIN
    IF (SELECT count(*) FROM public."Tool_Catalog" WHERE tool_specific_limits->>'runtime_service' = 'market-ai-orc'
          AND ((tool_name = 'create_analysis_spec' AND version = 'v3') OR (tool_name = 'prepare_analysis_data' AND version = 'v1')
               OR (tool_name = 'run_python_analysis' AND version = 'v4') OR (tool_name = 'get_dimension_values' AND version = 'v1'))
          AND NOT is_active) <> 4 THEN
        RAISE EXCEPTION 'Expected four inactive two-path tool registrations';
    END IF;
END;
$verify$;

COMMIT;
